// "Nope"

var n = 20;
var iNope, jNope;
var N_FRAMES = 120;

function setup() {
  createCanvas(500, 500);
  iNope = ~~random(n/5, 4*n/5);
  jNope = ~~random(n/5, 4*n/5);
}

function draw() {
  background("#fffcf2");

  let t = TAU*(frameCount%N_FRAMES)/N_FRAMES;

  let margin = 50;
  let s = (width-2*margin)/n;

  for (let i = 0; i < n; i++) {
    let x = margin + i*s;
    for (let j = 0; j < n; j++) {
      let y = margin + j*s;

      noStroke();
      let d = dist(x+s/2, y+s/2, width/2, height/2);
      let theta = atan2(y+s/2-height/2, x+s/2-width/2)+PI+d/30;
      fill(rainbow(theta/TAU));
      let z = (sin(d/20-t)+1)/2;
      if (i == iNope && j == jNope) {
        fill(rainbow(t/TAU));
        z = noise(1+cos(t), 1+sin(t));
      }
      rect(x, y, z*s, s);

      stroke(0);
      strokeWeight(1.5);
      noFill();
      square(x, y, s);
    }
  }
}

function rainbow(t) {
  let palette = ["#abcd5e", "#14976b", "#2b67af", "#62b6de", "#f589a3", "#ef562f", "#fc8405", "#f9d531"];
  let i = floor(palette.length*t);
  let amt = fract(palette.length*t);
  return lerpColor(color(palette[i%palette.length]), color(palette[(i+1)%palette.length]), amt);
}
